WITH scored AS (SELECT *, FIRST_VALUE(job_title) IGNORE NULLS OVER (PARTITION BY dept_id, manager_id ORDER BY hire_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_job_title, ROUND(salary / SUM(salary) OVER (PARTITION BY job_title), 4) AS salary_share, LAST_VALUE(level) IGNORE NULLS OVER (PARTITION BY manager_id ORDER BY hire_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_level, PERCENT_RANK() OVER (PARTITION BY level ORDER BY salary) AS salary_percent_rank, FIRST_VALUE(job_title, TRUE) OVER (PARTITION BY level ORDER BY hire_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_job_title_2 FROM employees) SELECT s.id, s.full_name, s.email, s.dept_id, s.manager_id, s.salary, s.last_known_level, s.salary_percent_rank, s.first_known_job_title_2, (SELECT MAX(x.salary) FROM employees x WHERE x.dept_id = s.dept_id) AS max_employee_salary FROM scored s ORDER BY salary_percent_rank DESC NULLS LAST, dept_id DESC
